def generate_trip_photo_thumbnail_task(photo_id: str) -> None:
    """Generate a thumbnail for an uploaded trip video photo."""
    from events.media_services import MediaStorageService
    from trips.models import TripPhoto

    try:
        photo = TripPhoto.objects.select_related("trip").get(id=photo_id)
    except TripPhoto.DoesNotExist:
        logger.warning("TripPhoto %s not found for thumbnail generation", photo_id)
        return

    if photo.media_type != "VIDEO":
        logger.info(
            "Skipping thumbnail generation for non-video TripPhoto %s", photo_id
        )
        return

    thumbnail_key = (
        MediaStorageService.generate_video_thumbnail(
            photo.file_key,
            str(photo.trip_id),
            namespace="trips",
        )
        or ""
    )

    if thumbnail_key:
        photo.thumbnail_key = thumbnail_key
        photo.save(update_fields=["thumbnail_key"])
        logger.info("Generated thumbnail for TripPhoto %s", photo_id)
        return

    logger.warning("Thumbnail generation returned no result for TripPhoto %s", photo_id)


