def _outer_banks_retry_delay(
    retries: int,
    *,
    retry_after_seconds: int | None = None,
) -> int:
    if retry_after_seconds is not None:
        return max(1, retry_after_seconds + int(random.uniform(1, 5)))  # noqa: S311 -- retry jitter only

