import random
import time

from celery import shared_task
from django.contrib.auth import get_user_model
from django.utils import timezone

from calendars.models import InternalCalendar
from trips.models import TripInvite
from trips.services.notification_service import TripNotificationService

logger = logging.getLogger(__name__)
User = get_user_model()

OUTER_BANKS_DETAIL_JITTER_MIN_SECONDS = 1.0
OUTER_BANKS_DETAIL_JITTER_MAX_SECONDS = 3.0
OUTER_BANKS_DETAIL_MAX_RETRY_DELAY_SECONDS = 15 * 60


@shared_task
def sync_rss_feeds():
    """Sync all enabled RSS feed sources."""
    from trips.models import RSSFeedSource
    from trips.services.rss_feed_service import RSSFeedService

    service = RSSFeedService()
    sources = RSSFeedSource.objects.filter(is_enabled=True)

    for source in sources:
        try:
            result = service.sync_feed(source)
            logger.info(
                "RSS sync %s: created=%d updated=%d skipped=%d errors=%d",
                source.name,
                result["created"],
                result["updated"],
                result["skipped"],
                result["errors"],
            )
        except Exception:
            logger.exception("RSS sync failed for %s", source.name)


def _outer_banks_retry_delay(
    retries: int,
    *,
    retry_after_seconds: int | None = None,
) -> int:
    if retry_after_seconds is not None:
        return max(1, retry_after_seconds + int(random.uniform(1, 5)))  # noqa: S311 -- retry jitter only

    backoff = min(OUTER_BANKS_DETAIL_MAX_RETRY_DELAY_SECONDS, 60 * (2**retries))
    return max(1, int(backoff + random.uniform(1, 15)))  # noqa: S311 -- retry jitter only


def _sleep_between_outer_banks_detail_requests() -> None:
    # Sequential pacing here keeps batch hydrations polite even when the same
    # feed contains many items that would otherwise trigger rapid follow-up hits.
    time.sleep(
        random.uniform(  # noqa: S311 -- pacing jitter only
            OUTER_BANKS_DETAIL_JITTER_MIN_SECONDS,
            OUTER_BANKS_DETAIL_JITTER_MAX_SECONDS,
        )
    )


@shared_task(bind=True, max_retries=4)
def hydrate_outer_banks_event_details_batch_task(
    self,
    source_key: str,
    event_ids: list[int],
    *,
    force: bool = False,
) -> None:
    from trips.models import RegionEvent
    from trips.services.outer_banks_event_detail_hydration import (
        OuterBanksEventDetailHydrationService,
        SourceDetailHydrationRetryableError,
        is_outer_banks_event_source,
        needs_outer_banks_detail_hydration,
    )

    if not is_outer_banks_event_source(source_key):
        logger.info(
            "Skipping source detail hydration for unsupported source '%s'", source_key
        )
        return

    service = OuterBanksEventDetailHydrationService()
    has_fetched_detail = False

    for raw_event_id in event_ids:
        try:
            event = RegionEvent.objects.select_related("event_source").get(
                id=int(raw_event_id)
            )
        except (TypeError, ValueError, RegionEvent.DoesNotExist):
            logger.warning(
                "Skipping missing or invalid RegionEvent id '%s' in source detail hydration batch",
                raw_event_id,
            )
            continue

        if not needs_outer_banks_detail_hydration(event, force=force):
            continue

        if has_fetched_detail:
            _sleep_between_outer_banks_detail_requests()

        try:
            service.hydrate_event(event.id, force=force)
        except SourceDetailHydrationRetryableError as exc:
            if self.request.retries >= self.max_retries:
                service.mark_failed(event.id, str(exc))
                continue
            raise self.retry(
                exc=exc,
                countdown=_outer_banks_retry_delay(
                    self.request.retries,
                    retry_after_seconds=exc.retry_after_seconds,
                ),
            ) from exc
        except Exception as exc:
            service.mark_failed(event.id, str(exc))
            logger.exception(
                "Outer Banks source detail hydration failed for RegionEvent %s",
                event.id,
            )
            continue

        has_fetched_detail = True


@shared_task(
    bind=True,
    max_retries=3,
    default_retry_delay=60,
    autoretry_for=(Exception,),
    retry_backoff=True,
)
def enrich_region_event_place_task(self, region_event_id: int) -> None:
    """Enrich an imported RegionEvent with Google Places data."""
    from trips.services.region_event_place_enrichment import (
        RegionEventPlaceEnrichmentService,
    )

    service = RegionEventPlaceEnrichmentService()
    event = service.enrich_event(region_event_id)
    if (
        event is not None
        and getattr(event, "matched_business_id", None)
        and getattr(event, "location_match_source", "") == "GOOGLE_FALLBACK"
    ):
        backfill_google_import_business_listing_task.delay(event.matched_business_id)


@shared_task
def backfill_google_import_business_listing_task(business_listing_id: int) -> None:
    """Backfill matching RegionEvents after a Google auto-import listing update."""
    from regions.cache import invalidate_explore_cache, invalidate_region_detail_cache
    from trips.models import BusinessListing
    from trips.services.business_listing_google_enrichment import (
        BusinessListingGoogleEnrichmentService,
    )

    try:
        listing = BusinessListing.objects.select_related("region").get(
            id=business_listing_id
        )
    except BusinessListing.DoesNotExist:
        logger.warning(
            "BusinessListing %s not found for Google import backfill",
            business_listing_id,
        )
        return

    service = BusinessListingGoogleEnrichmentService()
    service.backfill_listing_events(listing)
    invalidate_region_detail_cache(listing.region)
    invalidate_explore_cache()


@shared_task
def refresh_trip_property_listing_preview_task(trip_property_id: str) -> None:
    """Refresh best-effort metadata for a trip property listing URL."""
    from trips.services.listing_preview_service import ListingPreviewService

    service = ListingPreviewService()
    try:
        service.refresh_trip_property_preview(trip_property_id)
    except Exception:
        logger.exception(
            "Unexpected error refreshing listing preview for TripProperty %s",
            trip_property_id,
        )


@shared_task
def deactivate_past_trip_calendars() -> None:
    """Deactivate internal calendars for trips that have ended."""
    try:
        today = timezone.now().date()
        count = InternalCalendar.objects.filter(
            trip__end_date__lt=today,
            trip__deleted_at__isnull=True,
            is_active=True,
        ).update(is_active=False, updated_at=timezone.now())

        if count:
            logger.info("Deactivated %d past trip calendar(s)", count)
    except Exception:
        logger.exception("Error in deactivate_past_trip_calendars")


@shared_task
def generate_trip_photo_thumbnail_task(photo_id: str) -> None:
    """Generate a thumbnail for an uploaded trip video photo."""
    from events.media_services import MediaStorageService
    from trips.models import TripPhoto

    try:
        photo = TripPhoto.objects.select_related("trip").get(id=photo_id)
    except TripPhoto.DoesNotExist:
        logger.warning("TripPhoto %s not found for thumbnail generation", photo_id)
        return

    if photo.media_type != "VIDEO":
        logger.info(
            "Skipping thumbnail generation for non-video TripPhoto %s", photo_id
        )
        return

    thumbnail_key = (
        MediaStorageService.generate_video_thumbnail(
            photo.file_key,
            str(photo.trip_id),
            namespace="trips",
        )
        or ""
    )

    if thumbnail_key:
        photo.thumbnail_key = thumbnail_key
        photo.save(update_fields=["thumbnail_key"])
        logger.info("Generated thumbnail for TripPhoto %s", photo_id)
        return

    logger.warning("Thumbnail generation returned no result for TripPhoto %s", photo_id)


